import { spawnSync } from 'node:child_process'
import { readFileSync, rmSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

import type { TestProject } from 'vitest/node'

const here = path.dirname(fileURLToPath(import.meta.url))
// wrangler appends ndjson records here (WRANGLER_OUTPUT_FILE_PATH), one of
// which is {type: 'deploy', targets: [urls]}.
const outputFile = path.join(here, '.deploy-output.json')

function wrangler(args: string[]) {
  const result = spawnSync(
    process.platform === 'win32' ? 'npx.cmd' : 'npx',
    ['wrangler', ...args, '--config', path.join(here, 'wrangler.jsonc')],
    {
      cwd: here,
      encoding: 'utf8',
      timeout: 240_000,
      env: {
        ...process.env,
        // --temporary only works unauthenticated; drop any ambient Cloudflare
        // auth so a logged-in local environment behaves like CI.
        CLOUDFLARE_API_TOKEN: '',
        WRANGLER_OUTPUT_FILE_PATH: outputFile,
      },
    }
  )
  return { ...result, output: `${result.stdout ?? ''}\n${result.stderr ?? ''}` }
}

// A temporary deploy lands on a brand-new account subdomain
// (<worker>.<random-name>.workers.dev), and until both the route and the
// script propagate to the edge Cloudflare serves an HTML error page: a 404
// ("nothing is here yet") for the missing route, or a 500 ("Script not
// found") from a colo that already has the route but not the script. Wait
// for the worker itself to answer (405 to GET, worker.mjs is POST-only) so
// the test's own retries only have to absorb transient network failures.
const propagationErrorTitle = /Script not found/i

async function waitUntilLive(workerUrl: string, timeoutMs = 240_000) {
  const deadline = Date.now() + timeoutMs
  for (;;) {
    // Thrown fetch errors (DNS/connect for the fresh subdomain) are also
    // transient — keep waiting on those, but fail fast on anything that is
    // not a propagation error so real errors surface immediately.
    const response = await fetch(workerUrl).catch((err) => {
      console.log(`Worker not reachable yet (${err}), waiting...`)
      return undefined
    })
    if (response) {
      if (response.status === 405) {
        return
      }
      if (response.status === 404) {
        console.log('Worker route not live yet (404), waiting...')
      } else {
        const text = await response.text()
        const title = text.match(/<title>(.*?)<\/title>/is)?.[1]?.trim()
        if (!propagationErrorTitle.test(title ?? '')) {
          throw new Error(
            `Worker at ${workerUrl} answered ${response.status}${
              title ? ` ("${title}")` : ''
            } — not a propagation error: ${text.slice(0, 200)}`
          )
        }
        console.log(
          `Worker script not live yet (${response.status}, "${title}"), waiting...`
        )
      }
    }
    if (Date.now() >= deadline) {
      throw new Error(
        `Worker at ${workerUrl} did not come up within ${timeoutMs / 1000}s of deploy`
      )
    }
    await new Promise((resolve) => setTimeout(resolve, 3_000))
  }
}

export default async function setup(project: TestProject) {
  rmSync(outputFile, { force: true })

  console.log('Deploying worker to a temporary Cloudflare preview account...')
  const deploy = wrangler(['deploy', '--temporary'])
  if (deploy.status !== 0) {
    console.error(deploy.output)
    throw new Error(`wrangler deploy --temporary failed (${deploy.status})`)
  }

  let workerUrl: string | undefined
  for (const line of readFileSync(outputFile, 'utf8').split('\n')) {
    if (!line.trim()) {
      continue
    }
    const record = JSON.parse(line)
    if (record.type === 'deploy' && record.targets?.length) {
      workerUrl = record.targets[0]
    }
  }
  if (!workerUrl) {
    console.error(deploy.output)
    throw new Error(
      'Could not find the deployed workers.dev URL in wrangler output'
    )
  }

  console.log(`Deployed: ${workerUrl}`)
  await waitUntilLive(workerUrl)
  console.log('Worker is live.')
  project.provide('cfWorkerUrl', workerUrl)

  return function teardown() {
    // Best-effort — the preview account expires on its own.
    const cleanup = wrangler(['delete', '--force', '--temporary'])
    if (cleanup.status !== 0) {
      console.warn(
        'wrangler delete failed (ignored):',
        cleanup.output.trim().split('\n').at(-1)
      )
    }
    rmSync(outputFile, { force: true })
  }
}

declare module 'vitest' {
  export interface ProvidedContext {
    cfWorkerUrl: string
  }
}

import { test as base, onTestFailed } from 'vitest'
import {
  BuildInfo,
  LogEntry,
  Sandbox,
  SandboxOpts,
  Template,
  TemplateClass,
  Volume,
} from '../src'
import { template } from './template'

interface SandboxFixture {
  sandbox: Sandbox
  template: string
  sandboxTestId: string
  sandboxOpts: Partial<SandboxOpts>
}

interface VolumeFixture {
  volume: Volume
}

interface BuildTemplateFixture {
  buildTemplate: (
    template: TemplateClass,
    options?: { name?: string; skipCache?: boolean },
    onBuildLogs?: (logEntry: LogEntry) => void
  ) => Promise<BuildInfo>
}

async function buildTemplate(
  template: TemplateClass,
  options?: { name?: string; skipCache?: boolean },
  onBuildLogs?: (logEntry: LogEntry) => void
): Promise<BuildInfo> {
  const buildName = options?.name || `e2b-test-${generateRandomString()}`
  const buildInfo: { templateId?: string; buildId?: string } = {}

  const captureLogs = (log: LogEntry) => {
    if (log.message.includes('Template created with ID:')) {
      const match = log.message.match(
        /Template created with ID: ([^,]+), Build ID: (.+)/
      )
      if (match) {
        buildInfo.templateId = match[1]
        buildInfo.buildId = match[2]
      }
    }
    onBuildLogs?.(log)
  }

  try {
    return await Template.build(template, buildName, {
      cpuCount: 1,
      memoryMB: 1024,
      skipCache: options?.skipCache,
      onBuildLogs: captureLogs,
    })
  } catch (e) {
    console.error(
      `\n[BUILD FAILED] name=${buildName}, ` +
        `template_id=${buildInfo.templateId}, ` +
        `build_id=${buildInfo.buildId}, error=${e}`
    )
    throw e
  }
}

export const sandboxTest = base.extend<SandboxFixture>({
  template,
  sandboxTestId: [
    // eslint-disable-next-line no-empty-pattern
    async ({}, use) => {
      const id = `test-${generateRandomString()}`
      await use(id)
    },
    { auto: true },
  ],
  sandboxOpts: {},
  sandbox: [
    async ({ sandboxTestId, sandboxOpts }, use) => {
      const sandbox = await Sandbox.create(template, {
        metadata: { sandboxTestId },
        timeoutMs: 300_000,
        ...sandboxOpts,
      })
      onTestFailed(() => {
        console.error(`\n[TEST FAILED] Sandbox ID: ${sandbox.sandboxId}`)
      })
      try {
        await use(sandbox)
      } finally {
        try {
          await sandbox.kill()
        } catch (err) {
          if (!isDebug) {
            console.warn(
              'Failed to kill sandbox — this is expected if the test runs with local envd.'
            )
          }
        }
      }
    },
    { auto: false },
  ],
})

export const buildTemplateTest = base.extend<BuildTemplateFixture>({
  buildTemplate: [
    // eslint-disable-next-line no-empty-pattern
    async ({}, use) => {
      await use(buildTemplate)
    },
    { auto: true },
  ],
})

export const volumeTest = base.extend<VolumeFixture>({
  volume: [
    // eslint-disable-next-line no-empty-pattern
    async ({}, use) => {
      // The placeholder key keeps the mocked volume tests independent of
      // E2B_API_KEY being set in the environment.
      const volume = await Volume.create(`test-vol-${generateRandomString()}`, {
        apiKey: [REDACTED] ?? TEST_API_KEY,
      })
      onTestFailed(() => {
        console.error(`\n[TEST FAILED] Volume ID: ${volume.volumeId}`)
      })
      try {
        await use(volume)
      } finally {
        try {
          await Volume.destroy(volume.volumeId, {
            apiKey: [REDACTED] ?? TEST_API_KEY,
          })
        } catch {
          // Ignore cleanup errors
        }
      }
    },
    { auto: false },
  ],
})

export const isDebug = process.env.E2B_DEBUG !== undefined

/** The sandbox `git` API is deprecated; its tests only run when opted in. */
export const isGitTestsEnabled = process.env.ENABLE_GIT_TESTS !== undefined

export const gitTest = sandboxTest.skipIf(!isGitTestsEnabled)

/** Placeholder API key with a valid format for tests that don't hit the API. */
export const TEST_API_KEY = `e2b_${'0'.repeat(40)}`

/**
 * Command that serves the working directory on `port` with CORS enabled, for
 * tests that read a response from a server running inside the sandbox.
 *
 * Use this instead of `python -m http.server`, which sends no CORS headers: a
 * browser only exposes a cross-origin response to JS when the server opts in,
 * so there the fetch fails as an opaque `TypeError: Failed to fetch` no matter
 * what the server answered. Opting in is what a real browser app's own server
 * does too, and it's only ever the user's server that has to — the responses
 * the sandbox proxy synthesizes carry their own CORS headers (belt#2068; the
 * traffic-token paths are still awaiting the orchestrator rollout, which is why
 * `sandbox requires traffic access token` is red on the browser leg).
 *
 * `Access-Control-Allow-Headers` and `do_OPTIONS` cover requests that carry a
 * custom header, which the browser preflights before sending.
 */
export function corsHttpServerCmd(port: number): string {
  return `python3 -c "
from http.server import SimpleHTTPRequestHandler, ThreadingHTTPServer

class Handler(SimpleHTTPRequestHandler):
    def end_headers(self):
        self.send_header('Access-Control-Allow-Origin', '*')
        self.send_header('Access-Control-Allow-Headers', '*')
        SimpleHTTPRequestHandler.end_headers(self)

    def do_OPTIONS(self):
        self.send_response(204)
        self.end_headers()

ThreadingHTTPServer(('', ${port}), Handler).serve_forever()
"`
}

function generateRandomString(length: number = 8): string {
  return Math.random()
    .toString(36)
    .substring(2, length + 2)
}

export async function wait(ms: number) {
  return new Promise((resolve) => setTimeout(resolve, ms))
}

/**
 * Poll `url` until it returns `expectedStatus`, tolerating connection errors —
 * the sandbox proxy may not have a route until the guest server is ready.
 * Returns the body text of the matching response.
 */
export async function waitForHttpStatus(
  url: string,
  expectedStatus: number,
  { init, timeoutMs = 30_000 }: { init?: RequestInit; timeoutMs?: number } = {}
): Promise<string> {
  const deadline = Date.now() + timeoutMs
  let lastStatus: number | undefined

  while (Date.now() < deadline) {
    const requestTimeoutMs = Math.min(5_000, deadline - Date.now())
    const controller = new AbortController()
    const requestTimeout = setTimeout(
      () => controller.abort(),
      requestTimeoutMs
    )
    try {
      const response = await fetch(url, {
        ...init,
        signal: controller.signal,
      })
      lastStatus = response.status
      if (lastStatus === expectedStatus) {
        return await response.text()
      }
      await response.body?.cancel()
    } catch {
      // The sandbox proxy may not have a route until the guest server is ready.
    } finally {
      clearTimeout(requestTimeout)
    }
    await wait(500)
  }

  throw new Error(
    `Timed out waiting for ${url} to return ${expectedStatus}; last status: ${lastStatus ?? 'request failed'}`
  )
}

/**
 * Returns the API URL for the given path, using E2B_DOMAIN env var.
 * Supports msw path parameters like :templateID
 */
export function apiUrl(path: string): string {
  const domain = process.env.E2B_DOMAIN || 'e2b.app'
  return `https://api.${domain}${path}`
}

export { template }

import { vi } from 'vitest'

// msw mocks the network by patching `globalThis.fetch`, which the undici
// dispatcher the SDK uses on Node bypasses entirely — mocked requests would
// escape to the real API. Registered via `setupFiles` for every Node project,
// this reroutes the SDK through its real undici-unavailable fallback, which
// late-binds `globalThis.fetch`, so msw suites need no per-file mock. Tests
// that inject their own `loadUndici` (the api/envd transport suites) keep it,
// so the dispatcher wiring itself stays covered.
vi.mock('../src/undici', async (importOriginal) => {
  const original = await importOriginal<typeof import('../src/undici')>()
  return {
    ...original,
    buildDispatchedFetch: (
      options: Parameters<typeof original.buildDispatchedFetch>[0]
    ) =>
      original.buildDispatchedFetch({
        ...options,
        loadUndici: options.loadUndici ?? (async () => undefined),
      }),
  }
})

import { buildTemplateTest } from '../../setup'
import { DockerfileSyntaxError, Template } from '../../../src'
import { InstructionType } from '../../../src/template/types'
import { assert } from 'vitest'

buildTemplateTest('fromDockerfile', async () => {
  const dockerfile = `FROM node:24
WORKDIR /app
COPY package.json .
RUN npm install
ENTRYPOINT ["sleep", "20"]`

  const template = Template().fromDockerfile(dockerfile)

  assert.equal(
    // @ts-expect-error - baseImage is not a property of TemplateBuilder
    template.baseImage,
    'node:24'
  )
  assert.equal(
    // @ts-expect-error - instructions is not a property of TemplateBuilder
    template.instructions[1].type,
    InstructionType.WORKDIR
  )
  assert.equal(
    // @ts-expect-error - instructions is not a property of TemplateBuilder
    template.instructions[1].args[0],
    '/'
  )
  assert.equal(
    // @ts-expect-error - instructions is not a property of TemplateBuilder
    template.instructions[2].type,
    InstructionType.WORKDIR
  )
  assert.equal(
    // @ts-expect-error - instructions is not a property of TemplateBuilder
    template.instructions[2].args[0],
    '/app'
  )
  assert.equal(
    // @ts-expect-error - instructions is not a property of TemplateBuilder
    template.instructions[3].type,
    InstructionType.COPY
  )
  assert.equal(
    // @ts-expect-error - instructions is not a property of TemplateBuilder
    template.instructions[3].args[0],
    'package.json'
  )
  assert.equal(
    // @ts-expect-error - instructions is not a property of TemplateBuilder
    template.instructions[3].args[1],
    '.'
  )
  assert.equal(
    // @ts-expect-error - instructions is not a property of TemplateBuilder
    template.instructions[4].type,
    InstructionType.RUN
  )
  assert.equal(
    // @ts-expect-error - instructions is not a property of TemplateBuilder
    template.instructions[4].args[0],
    'npm install'
  )
  assert.equal(
    // @ts-expect-error - instructions is not a property of TemplateBuilder
    template.instructions[5].type,
    InstructionType.USER
  )
  assert.equal(
    // @ts-expect-error - instructions is not a property of TemplateBuilder
    template.instructions[5].args[0],
    'user'
  )
  assert.equal(
    // @ts-expect-error - startCmd is not a property of TemplateBuilder
    template.startCmd,
    'sleep 20'
  )
})

buildTemplateTest('fromDockerfile with default user and workdir', () => {
  const dockerfile = 'FROM node:24'
  const template = Template().fromDockerfile(dockerfile)

  assert.equal(
    // @ts-expect-error - instructions is not a property of TemplateBuilder
    template.instructions[template.instructions.length - 2].type,
    InstructionType.USER
  )
  assert.equal(
    // @ts-expect-error - instructions is not a property of TemplateBuilder
    template.instructions[template.instructions.length - 2].args[0],
    'user'
  )
  assert.equal(
    // @ts-expect-error - instructions is not a property of TemplateBuilder
    template.instructions[template.instructions.length - 1].type,
    InstructionType.WORKDIR
  )
  assert.equal(
    // @ts-expect-error - instructions is not a property of TemplateBuilder
    template.instructions[template.instructions.length - 1].args[0],
    '/home/user'
  )
})

buildTemplateTest('fromDockerfile with custom user and workdir', () => {
  const dockerfile = 'FROM node:24\nUSER mish\nWORKDIR /home/mish'
  const template = Template().fromDockerfile(dockerfile)

  assert.equal(
    // @ts-expect-error - instructions is not a property of TemplateBuilder
    template.instructions[template.instructions.length - 2].type,
    InstructionType.USER
  )
  assert.equal(
    // @ts-expect-error - instructions is not a property of TemplateBuilder
    template.instructions[template.instructions.length - 2].args[0],
    'mish'
  )
  assert.equal(
    // @ts-expect-error - instructions is not a property of TemplateBuilder
    template.instructions[template.instructions.length - 1].type,
    InstructionType.WORKDIR
  )
  assert.equal(
    // @ts-expect-error - instructions is not a property of TemplateBuilder
    template.instructions[template.instructions.length - 1].args[0],
    '/home/mish'
  )
})

buildTemplateTest('fromDockerfile with multi-source COPY', () => {
  const dockerfile = `FROM node:24
COPY file1.txt file2.txt file3.txt /dest/`

  const template = Template().fromDockerfile(dockerfile)

  // After initial USER root and WORKDIR /, the multi-source COPY should
  // expand into one COPY instruction per source.
  // @ts-expect-error - instructions is not a property of TemplateBuilder
  const copyInstructions = template.instructions.filter(
    (i: { type: InstructionType }) => i.type === InstructionType.COPY
  )

  assert.equal(copyInstructions.length, 3)
  assert.equal(copyInstructions[0].args[0], 'file1.txt')
  assert.equal(copyInstructions[0].args[1], '/dest/')
  assert.equal(copyInstructions[1].args[0], 'file2.txt')
  assert.equal(copyInstructions[1].args[1], '/dest/')
  assert.equal(copyInstructions[2].args[0], 'file3.txt')
  assert.equal(copyInstructions[2].args[1], '/dest/')
})

buildTemplateTest('fromDockerfile with multi-source COPY --chown', () => {
  const dockerfile = `FROM node:24
COPY --chown=myuser:mygroup pkg.json pkg-lock.json /app/`

  const template = Template().fromDockerfile(dockerfile)

  // @ts-expect-error - instructions is not a property of TemplateBuilder
  const copyInstructions = template.instructions.filter(
    (i: { type: InstructionType }) => i.type === InstructionType.COPY
  )

  assert.equal(copyInstructions.length, 2)
  assert.equal(copyInstructions[0].args[0], 'pkg.json')
  assert.equal(copyInstructions[0].args[1], '/app/')
  assert.equal(copyInstructions[0].args[2], 'myuser:mygroup')
  assert.equal(copyInstructions[1].args[0], 'pkg-lock.json')
  assert.equal(copyInstructions[1].args[1], '/app/')
  assert.equal(copyInstructions[1].args[2], 'myuser:mygroup')
})

buildTemplateTest('fromDockerfile with COPY --chown', () => {
  const dockerfile = `FROM node:24
COPY --chown=myuser:mygroup app.js /app/
COPY --chown=anotheruser config.json /config/`

  const template = Template().fromDockerfile(dockerfile)

  // First COPY instruction (after initial USER root and WORKDIR /)
  // @ts-expect-error - instructions is not a property of TemplateBuilder
  const copyInstruction1 = template.instructions[2]
  assert.equal(copyInstruction1.type, InstructionType.COPY)
  assert.equal(copyInstruction1.args[0], 'app.js')
  assert.equal(copyInstruction1.args[1], '/app/')
  assert.equal(copyInstruction1.args[2], 'myuser:mygroup') // user from --chown

  // Second COPY instruction
  // @ts-expect-error - instructions is not a property of TemplateBuilder
  const copyInstruction2 = template.instructions[3]
  assert.equal(copyInstruction2.type, InstructionType.COPY)
  assert.equal(copyInstruction2.args[0], 'config.json')
  assert.equal(copyInstruction2.args[1], '/config/')
  assert.equal(copyInstruction2.args[2], 'anotheruser') // user from --chown (without group)
})

function instructionsOf(template: unknown) {
  // @ts-expect-error - instructions is not a property of TemplateBuilder
  return template.instructions as { type: InstructionType; args: string[] }[]
}

buildTemplateTest('fromDockerfile with quoted ENV and ARG values', () => {
  const dockerfile = `FROM node:24
ENV A="hello world" B='single quoted' C=plain D=escaped\\ space
ENV LEGACY some value with  spaces
ENV MULTI=1 \\
    # comment inside continuation
    LINE="two \\
words"
ARG VERSION=1.0 NAME="with space" EMPTY
ENV REF="$HOME/bin:\${PATH}"`

  const template = Template().fromDockerfile(dockerfile)
  const envs = instructionsOf(template)
    .filter((i) => i.type === InstructionType.ENV)
    .map((i) => i.args)

  assert.deepEqual(envs, [
    [
      'A',
      'hello world',
      'B',
      'single quoted',
      'C',
      'plain',
      'D',
      'escaped space',
    ],
    ['LEGACY', 'some value with  spaces'],
    ['MULTI', '1', 'LINE', 'two words'],
    ['VERSION', '1.0', 'NAME', 'with space', 'EMPTY', ''],
    ['REF', '$HOME/bin:${PATH}'],
  ])
})

buildTemplateTest(
  'fromDockerfile with mixed-case keywords and AS alias',
  () => {
    const dockerfile = `from node:24 As Builder
run echo hi
Workdir /app
uSeR node`

    const template = Template().fromDockerfile(dockerfile)
    // @ts-expect-error - baseImage is not a property of TemplateBuilder
    assert.equal(template.baseImage, 'node:24')
    const instructions = instructionsOf(template)
    assert.equal(instructions[2].type, InstructionType.RUN)
    assert.deepEqual(instructions[2].args, ['echo hi'])
    assert.deepEqual(instructions[3].args, ['/app'])
    assert.deepEqual(instructions[4].args, ['node'])
  }
)

buildTemplateTest(
  'fromDockerfile preserves whitespace in RUN and uses shell form',
  () => {
    const dockerfile = `FROM node:24
RUN echo "a   b"   &&   \\
    echo 'c   d'
RUN ["echo", "hello world", "it's"]`

    const template = Template().fromDockerfile(dockerfile)
    const runs = instructionsOf(template)
      .filter((i) => i.type === InstructionType.RUN)
      .map((i) => i.args[0])

    assert.deepEqual(runs, [
      `echo "a   b"   &&       echo 'c   d'`,
      `echo 'hello world' 'it'"'"'s'`,
    ])
  }
)

buildTemplateTest('fromDockerfile with escape directive', () => {
  const dockerfile = `# escape=\`
FROM node:24
RUN echo one \`
    && echo two
ENV P="C:\\tools"`

  const template = Template().fromDockerfile(dockerfile)
  const instructions = instructionsOf(template)
  assert.deepEqual(instructions[2].args, ['echo one     && echo two'])
  assert.deepEqual(instructions[3].args, ['P', 'C:\\tools'])
})

buildTemplateTest('fromDockerfile with COPY --chmod and quoted paths', () => {
  const dockerfile = `FROM node:24
COPY --chmod=755 --chown=app:app "my file.txt" other.txt /dest/
COPY ["json file.txt", "/dest/"]
ADD archive.tar.gz /opt/`

  const template = Template().fromDockerfile(dockerfile)
  const copies = instructionsOf(template)
    .filter((i) => i.type === InstructionType.COPY)
    .map((i) => i.args)

  assert.deepEqual(copies, [
    ['my file.txt', '/dest/', 'app:app', '0755'],
    ['other.txt', '/dest/', 'app:app', '0755'],
    ['json file.txt', '/dest/', '', ''],
    ['archive.tar.gz', '/opt/', '', ''],
  ])
})

buildTemplateTest('fromDockerfile with heredocs', () => {
  const dockerfile = `FROM node:24
RUN <<EOF
npm install
npm run build
EOF
RUN <<-EOT
\techo tabbed
EOT
RUN python3 - <<PY
print("hi")
PY
RUN 3<<FD
touch /tmp/fd
FD
COPY <<'CONF' /etc/app.conf
key=$VALUE
CONF`

  const template = Template().fromDockerfile(dockerfile)
  const runs = instructionsOf(template)
    .filter((i) => i.type === InstructionType.RUN)
    .map((i) => i.args[0])

  assert.deepEqual(runs, [
    'npm install\nnpm run build\n',
    'echo tabbed\n',
    'python3 - <<PY\nprint("hi")\nPY',
    'touch /tmp/fd\n',
    `E2B_HEREDOC_DEST=/etc/app.conf\nif [ -d "$E2B_HEREDOC_DEST" ]; then E2B_HEREDOC_DEST="$E2B_HEREDOC_DEST"/CONF; fi\nmkdir -p "$(dirname "$E2B_HEREDOC_DEST")" && cat <<'E2B_HEREDOC_CONF' >"$E2B_HEREDOC_DEST"\nkey=$VALUE\nE2B_HEREDOC_CONF`,
  ])
})

buildTemplateTest('fromDockerfile COPY heredoc runs as root', () => {
  const dockerfile = `FROM node:24
USER app
COPY <<EOF /etc/app.conf
E2B_HEREDOC_EOF
x=1
EOF`

  const template = Template().fromDockerfile(dockerfile)
  const runs = instructionsOf(template)
    .filter((i) => i.type === InstructionType.RUN)
    .map((i) => i.args)

