// The end of the story the fake undici above can only imply: real undici,
// asked to send a Request it did not mint, throws before touching the network.
test.skipIf(runtime !== 'node')(
  'sends a disowned Request through the real undici fetch',
  async () => {
    const undici = (await loadUndici()) as UndiciModule & {
      MockAgent: new (options: { connections?: number }) => {
        get(origin: string): {
          intercept(options: {
            path: string
            method: string
            headers: Record<string, string>
          }): { reply(status: number, body: string): void }
        }
        disableNetConnect(): void
        assertNoPendingInterceptors(): void
        close(): Promise<void>
      }
    }
    const mockAgent = new undici.MockAgent({ connections: 1 })
    mockAgent.disableNetConnect()
    // An unmatched request throws, so this is the assertion: real undici has to
    // see the method, path and headers of the Request it was handed.
    mockAgent
      .get('https://api.example.test')
      .intercept({
        path: '/sandboxes',
        method: 'POST',
        headers: { 'x-api-key': 'secret' },
      })
      .reply(201, 'created')

    const { MintingRequest, GlobalShimRequest } = foreignRequestClasses()
    const request = new MintingRequest('https://api.example.test/sandboxes', {
      method: 'POST',
      headers: { 'x-api-key': 'secret' },
    })

    vi.stubGlobal('Request', GlobalShimRequest)
    try {
      const fetcher = await buildDispatchedFetch({
        connections: 1,
        loadUndici: async () => ({
          ...undici,
          // buildDispatchedFetch builds its own dispatcher; hand it the mock.
          Agent: class {
            constructor() {
              return mockAgent
            }
          } as unknown as UndiciModule['Agent'],
        }),
      })

      const response = await fetcher(request)
      expect(response.status).toBe(201)
      expect(await response.text()).toBe('created')
    } finally {
      vi.unstubAllGlobals()
      mockAgent.assertNoPendingInterceptors()
      await mockAgent.close()
    }
  }
)

import { expect, inject, test } from 'vitest'

import { template } from '../../template'

test(
  'sandbox lifecycle inside a deployed Cloudflare Worker',
  // setup.mts waits for the fresh workers.dev subdomain to propagate before
  // tests run; these retries only absorb transient blips — a stray
  // propagation error page (404 "nothing is here yet" for the route, 500
  // "Script not found" from a colo that lags behind the one setup.mts
  // probed) or an undici DNS/connect error ("fetch failed"). Any other
  // Cloudflare error page is a real failure and propagates.
  {
    retry: {
      count: 10,
      delay: 3_000,
      condition: /non-JSON response \(404|Script not found|fetch failed/,
    },
  },
  async () => {
    // Deployed by setup.mts via `wrangler deploy --temporary`.
    const workerUrl = inject('cfWorkerUrl')
    expect(process.env.E2B_API_KEY, 'E2B_API_KEY is required').toBeDefined()

    const response = await fetch(workerUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        apiKey: [REDACTED],
        domain: process.env.E2B_DOMAIN || undefined,
        template,
      }),
    })

    const text = await response.text()
    let body: Record<string, unknown>
    try {
      body = JSON.parse(text)
    } catch {
      // Cloudflare edge error page — fail and let the retry kick in. The
      // page's <title> says which error it is (the truncated body is just
      // boilerplate shared by every Cloudflare error page).
      const title = text.match(/<title>(.*?)<\/title>/is)?.[1]?.trim()
      throw new Error(
        `non-JSON response (${response.status}${
          title ? `, "${title}"` : ''
        }): ${text.slice(0, 200)}`
      )
    }

    expect(body.error, 'worker reported an error').toBeUndefined()
    expect(response.status).toBe(200)
    expect(body.isRunning).toBe(true)
    expect(body.exitCode).toBe(0)
    expect(body.stdout).toBe('Hello, World!\n')
    expect(body.content).toBe('Hello, World!')
    expect(body.ok).toBe(true)
  }
)
